public class NonRefundablePlan implements RatePlan {
    private static final BigDecimal DISCOUNT_RATE = new BigDecimal("0.15");

    @Override
    public String getName() {
        return "NON_REFUNDABLE";
    }

    @Override
    public void validateAppliesTo(Room room, LocalDate checkIn, LocalDate checkOut, int guests, String companyCode) {
        // Non-refundable plan applies to all dates and guests
